            if grid[r][c] == color:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                if r < 21 and c < 21 and grid[r][c+1] == 0 and grid[r+1][c] == 0:
                    has_interior = True
    return min_r, max_r, min_c, max_c, has_interior

def find_all_frames(grid, color_target, bg=0):
    """Find all frames of a color"""
    result = []
    for color in set(v for row in grid for v in row if v != bg):
        rmin, rmax, cmin, cmax, interior = find_frame_bounds(grid, color)
        if rmax - rmin > 1 and cmax - cmin > 1:  # is a frame
            interior = rmax - rmin - 2 > 0 and cmax - cmin - 2 > 0
            result.append((color, rmin, rmax, cmin, cmax, interior))
        elif color == color_target:
            result.append((color, rmin, rmax, cmin, cmax, interior))
    return result

